```c
#define MAGIC            0x200006042018fffflu
#define SUPERBLOCK_CACHE 0xffffffc05f000000lu   // 512 B
#define INODEMAP_CACHE   0xffffffc05f000200lu   // 512 B  (1 sector = 4096 inodes)
#define BLOCKMAP_CACHE   0xffffffc05f000400lu   // 32 KiB (64 sectors = 262144 blocks)
#define INODE_CACHE      0xffffffc05f008400lu   // 512 B  (8 inodes/sector)
#define BLOCK_CACHE      0xffffffc05f008600lu   // 4 KiB
#define FS_CACHE_END     0xffffffc05f009600lu
// superblock_t: 15 x uint64_t + uint8_t empty[392] == 512 B
// inode_t (64 B): mode, owner, size, direct_blocks[10], indirect_blocks[2], link (all u32)
// dir_entry_t (32 B): uint8_t type; uint8_t name[29]; uint16_t inode;  EMPTY=0 DIR=1 FILE=2
// dir_t: dir_entry_t entry[128]  == 4096 B
#define SUPERBLOCK_ID     4096
#define BLOCKMAP_BEGIN_ID 4097   // 64 sectors
#define INODEMAP_ID       4161
#define INODE_BEGIN_ID    4162   // 512 sectors -> 4096 inodes
#define BLOCK_BEGIN_ID    5120   // 8 sectors per 4 KiB block
// fd_t: uint16_t inode; uint16_t access; uint64_t rd_pos; uint64_t wr_pos;  fd_list[10]
// O_EMPTY 0, O_RDONLY 1, O_WRONLY 2, O_RDWR 3
